 words:[W("兄弟","xiōng|dì","พี่น้อง (ผู้ชาย)","ซง-ตี้","兄 (พี่ชาย) + 弟 (น้องชาย)","我有两个兄弟。","Wǒ yǒu liǎng ge xiōng|dì.","ฉันมีพี่น้องผู้ชายสองคน"),W("青少年","qīng|shào|nián","วัยรุ่น","ชิง-เส้า-เหนียน๋","青 (เขียว/อ่อน) + 少年 (เยาวชน)","青少年都爱玩游戏。","Qīng|shào|nián dōu ài wán yóu|xì.","วัยรุ่นชอบเล่นเกมกันทุกคน"),W("华裔","huá|yì","ลูกหลานชาวจีนโพ้นทะเล","หวา๋-อี้","华 (จีน) + 裔 (ลูกหลาน)","他是泰国华裔。","Tā shì Tài|guó huá|yì.","เขาเป็นลูกหลานชาวจีนในไทย"),W("敌人","dí|rén","ศัตรู","ตี๋-เริ๋น","敌 (ต่อต้าน) + 人 (คน)","他不是我的敌人。","Tā bú shì wǒ de dí|rén.","เขาไม่ใช่ศัตรูของฉัน"),W("伙伴","huǒ|bàn","เพื่อนร่วมทีม / คู่หู","หั่ว-ปั้น","伙 (กลุ่ม) + 伴 (เพื่อน)","他是我的好伙伴。","Tā shì wǒ de hǎo huǒ|bàn.","เขาเป็นคู่หูที่ดีของฉัน"),W("家庭","jiā|tíng","ครอบครัว","เจีย-ถิง๋","家 (บ้าน) + 庭 (ลาน)","我有一个幸福的家庭。","Wǒ yǒu yí ge xìng|fú de jiā|tíng.","ฉันมีครอบครัวที่อบอุ่น"),W("家务","jiā|wù","งานบ้าน","เจีย-อู้","家 (บ้าน) + 务 (ภารกิจ)","今天我们一起做家务吧。","jīn|tiān wǒ|men yì|qǐ zuò jiā|wù ba.","วันนี้เรามาช่วยกันทำงานบ้านกันเถอะ"),W("对象","duì|xiàng","คนรัก / เป้าหมาย","ตุ้ย-เซี่ยง","对 (คู่) + 象 (ภาพ)","他在找对象。","Tā zài zhǎo duì|xiàng.","เขากำลังหาแฟน")],
 sents:[["他/是/我/的/兄弟。", "tā/shì/wǒ/de/xiōng|dì.", "เขาเป็นพี่น้องของฉัน"], ["他/是/我/的/伙伴。", "tā/shì/wǒ/de/huǒ|bàn.", "เขาเป็นเพื่อนร่วมทีมของฉัน"], ["他/是/我/的/对象。", "tā/shì/wǒ/de/duì|xiàng.", "เขาเป็นคนรักของฉัน"], ["青少年/都/爱/玩/游戏。", "qīng|shào|nián/dōu/ài/wán/yóu|xì.", "วัยรุ่นชอบเล่นเกมกันทุกคน"], ["他/是/泰国/华裔。", "tā/shì/Tài|guó/huá|yì.", "เขาเป็นลูกหลานชาวจีนในไทย"], ["他/不/是/我/的/敌人。", "tā/bú/shì/wǒ/de/dí|rén.", "เขาไม่ใช่ศัตรูของฉัน"], ["我/有/一/个/幸福/的/家庭。", "wǒ/yǒu/yí/ge/xìng|fú/de/jiā|tíng.", "ฉันมีครอบครัวที่อบอุ่น"]],
